function switchTab(group, id, btn) {
  const parent = btn.closest('.section') || document.body;
  // Deactivate all tabs in the same tabs container
  const tabsContainer = btn.closest('.tabs');
  tabsContainer.querySelectorAll('.tab').forEach(t => {
    t.classList.remove('active');
    t.setAttribute('aria-selected', 'false');
  });
  btn.classList.add('active');
  btn.setAttribute('aria-selected', 'true');

  // Hide all tab content siblings
  const allContent = document.querySelectorAll('[id^="' + group + '-"]');
  allContent.forEach(el => el.classList.remove('active'));

  const target = document.getElementById(group + '-' + id);
  if (target) target.classList.add('active');
}

// Keyboard support for trend cards
document.querySelectorAll('.trend-card[tabindex="0"]').forEach(card => {
  card.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); card.click(); }
  });
});
</script>
