.timeframe-bar{display:flex;gap:2px;padding:0 16px;border-bottom:1px solid var(--border);height:38px;align-items:center;background:var(--bg-secondary);flex-shrink:0}
.tf-btn{padding:4px 10px;border-radius:4px;font-size:12px;font-weight:600;color:var(--text-muted);background:none;border:none;transition:all 150ms ease}
.tf-btn:hover{color:var(--text-primary);background:var(--bg-hover)}
.tf-btn.active{background:var(--accent);color:#fff}
.tf-sep{width:1px;height:16px;background:var(--border);margin:0 4px}
.chart-container{flex:1;position:relative;overflow:hidden;background:var(--bg-primary)}
.chart-svg{width:100%;height:100%;display:block}
.chart-overlay{position:absolute;top:12px;left:16px;display:flex;gap:12px;pointer-events:none}
.chart-ohlc{font-size:11.5px;color:var(--text-secondary);display:flex;gap:8px}
.chart-ohlc span{color:var(--text-primary);font-weight:600}

/* RIGHT PANEL */
.right-panel{width:280px;background:var(--bg-secondary);border-left:1px solid var(--border);display:flex;flex-direction:column;overflow:hidden;flex-shrink:0}
.panel-tabs{display:flex;border-bottom:1px solid var(--border)}
.panel-tab{flex:1;padding:10px 4px;text-align:center;font-size:12px;font-weight:600;color:var(--text-muted);background:none;border:none;cursor:pointer;border-bottom:2px solid transparent;transition:all 150ms ease}
.panel-tab.active{color:var(--accent);border-bottom-color:var(--accent)}
.panel-body{flex:1;overflow-y:auto;padding:14px}

/* DETAIL ROWS */
.detail-section{margin-bottom:18px}
.detail-section-title{font-size:10.5px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.7px;margin-bottom:10px}
.detail-row{display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid rgba(42,42,56,0.5);gap:8px}
.detail-row:last-child{border-bottom:none}
.detail-label{font-size:12px;color:var(--text-secondary);flex:1}
.detail-val{font-size:12px;font-weight:600;color:var(--text-primary);text-align:right;font-variant-numeric:tabular-nums}
.detail-val.pos{color:var(--green-text)}
.detail-val.neg{color:var(--red-text)}
.detail-val.neutral{color:var(--text-secondary)}

/* NEWS ITEM */
.news-item{padding:12px 0;border-bottom:1px solid var(--border);cursor:pointer}
.news-item:hover .news-title{color:var(--accent)}
.news-source{font-size:10.5px;font-weight:600;color:var(--accent);text-transform:uppercase;letter-spacing:0.4px;margin-bottom:4px}
.news-title{font-size:12.5px;color:var(--text-primary);line-height:1.4;transition:color 150ms}
.news-time{font-size:11px;color:var(--text-muted);margin-top:4px}

/* EARNINGS BADGE */
.earnings-badge{background:rgba(245,158,11,0.12);border:1px solid rgba(245,158,11,0.25);border-radius:5px;padding:6px 10px;font-size:12px;color:var(--gold);font-weight:600;margin-bottom:14px;display:flex;align-items:center;gap:6px}

/* PREMARKET */
.premarket-badge{background:rgba(41,98,255,0.1);border:1px solid rgba(41,98,255,0.2);border-radius:5px;padding:6px 10px;font-size:12px;margin-bottom:12px}
.pm-label{color:var(--text-muted);font-size:11px}
.pm-price{font-weight:700;color:#fff}
.pm-chg{color:var(--green-text);font-size:11px;font-weight:600}

/* FINANCIALS TABS */
.fin-tabs{display:flex;gap:2px;margin-bottom:12px}
.fin-tab{padding:4px 10px;border-radius:4px;font-size:11.5px;font-weight:500;color:var(--text-muted);background:none;border:1px solid transparent;cursor:pointer;transition:all 150ms}
.fin-tab.active{background:var(--bg-hover);color:#fff;border-color:var(--border)}

/* RATING */
.rating-bar{display:flex;align-items:center;gap:8px;margin-top:4px}
.rating-label{font-size:11px;color:var(--text-muted);width:44px}
.rating-track{flex:1;height:4px;background:var(--border);border-radius:2px;overflow:hidden}
.rating-fill{height:100%;border-radius:2px;background:var(--accent)}

/* RESPONSIVE */
@media(max-width:1200px){.right-panel{display:none}}
@media(max-width:900px){.watchlist{width:180px}}
@media(max-width:700px){.watchlist{display:none}}
</style>
