  const arrow = header.querySelector('.wl-cat-arrow');
  const isOpen = items.classList.contains('open');
  items.classList.toggle('open', !isOpen);
  arrow.classList.toggle('open', !isOpen);
  header.setAttribute('aria-expanded', String(!isOpen));
}

function selectSymbol(item) {
  document.querySelectorAll('.wl-item').forEach(i => i.classList.remove('active'));
  item.classList.add('active');
}

function setTF(btn) {
  document.querySelectorAll('.tf-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
}

function switchPanel(id, btn) {
  document.querySelectorAll('.panel-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.right-panel .panel-body').forEach(p => p.style.display = 'none');
  document.getElementById('panel-' + id).style.display = 'block';
}

function switchFinTab(id, btn) {
  document.querySelectorAll('.fin-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('fin-annual').style.display = id === 'annual' ? 'block' : 'none';
  document.getElementById('fin-quarterly').style.display = id === 'quarterly' ? 'block' : 'none';
}

// Keyboard support for watchlist
document.querySelectorAll('.wl-cat-header, .wl-item[tabindex="0"]').forEach(el => {
  el.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); el.click(); }
  });
});
