.idea-body{flex:1;padding:14px 16px;min-width:0}
.idea-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:8px}
.idea-ticker-row{display:flex;align-items:center;gap:8px}
.idea-ticker{font-size:13px;font-weight:700;color:#fff}
.idea-timeframe{font-size:11px;color:var(--text-muted);background:var(--bg-hover);padding:1px 6px;border-radius:3px}
.idea-editors-badge{display:flex;align-items:center;gap:4px;font-size:10.5px;font-weight:600;color:var(--gold);flex-shrink:0}
.idea-title{font-size:14px;font-weight:600;color:#fff;line-height:1.4;margin-bottom:8px}
.idea-desc{font-size:12.5px;color:var(--text-secondary);line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-bottom:10px}
.idea-footer{display:flex;align-items:center;justify-content:space-between;gap:8px}
.idea-author{display:flex;align-items:center;gap:8px}
.avatar{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#fff;flex-shrink:0}
.author-name{font-size:12px;color:var(--text-secondary)}
.idea-stats{display:flex;gap:12px;align-items:center}
.idea-stat{font-size:12px;color:var(--text-muted);display:flex;align-items:center;gap:4px}

/* VIDEO BADGE */
.video-badge{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:600;color:var(--red-text);background:rgba(239,83,80,0.1);border:1px solid rgba(239,83,80,0.2);border-radius:4px;padding:2px 7px;flex-shrink:0}

/* SIDEBAR */
.sidebar{display:flex;flex-direction:column;gap:16px}
.sidebar-card{background:var(--bg-card);border:1px solid var(--border);border-radius:10px;padding:16px}
.sidebar-title{font-size:13px;font-weight:700;color:#fff;margin-bottom:12px}
.sidebar-row{display:flex;align-items:center;justify-content:space-between;padding:7px 0;border-bottom:1px solid rgba(42,42,56,0.6);font-size:12.5px;cursor:pointer;transition:color 150ms}
.sidebar-row:hover{color:var(--accent)}
.sidebar-row:last-child{border-bottom:none}
.sidebar-sym{font-weight:700;color:#fff}
.sidebar-chg{font-weight:600;font-size:12px;padding:1px 6px;border-radius:3px}
.up{color:var(--green-text);background:rgba(38,166,154,0.12)}
.down{color:var(--red-text);background:rgba(239,83,80,0.12)}
.sidebar-tag{font-size:11px;font-weight:600;padding:2px 7px;border-radius:3px;background:rgba(41,98,255,0.12);color:var(--accent)}

/* PAGINATION */
.pagination{display:flex;align-items:center;justify-content:center;gap:4px;margin-top:24px}
.page-btn{width:32px;height:32px;display:flex;align-items:center;justify-content:center;border-radius:6px;font-size:13px;font-weight:500;color:var(--text-secondary);background:var(--bg-card);border:1px solid var(--border);cursor:pointer;transition:all 150ms ease}
.page-btn:hover{color:var(--text-primary);border-color:var(--border-light)}
.page-btn.active{background:var(--accent);color:#fff;border-color:var(--accent)}
.page-btn:disabled{opacity:0.4;cursor:not-allowed}

/* FOOTER */
.footer{background:var(--bg-secondary);border-top:1px solid var(--border);padding:40px 24px 28px;margin-top:48px}
.footer-inner{max-width:1400px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px}
.footer-logo{font-size:18px;font-weight:800;color:#fff}
.footer-logo span{color:var(--accent)}
.footer-links{display:flex;gap:20px;flex-wrap:wrap}
.footer-links a{font-size:13px;color:var(--text-secondary);transition:color 150ms}
.footer-links a:hover{color:var(--text-primary)}
.footer-copy{font-size:12px;color:var(--text-muted)}

@media(max-width:1100px){.page-body{grid-template-columns:1fr}.sidebar{display:none}}
@media(max-width:768px){.nav-links{display:none}.idea-chart{display:none}.page-body{padding:16px}}
@media(max-width:480px){.idea-card{flex-direction:column}.filter-bar{gap:8px}}
</style>
