function scrollToSection(id, btn) {
  document.querySelectorAll('.asset-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  const el = document.getElementById(id);
  if (el) { const top = el.getBoundingClientRect().top + window.scrollY - 120; window.scrollTo({ top, behavior: 'smooth' }); }
}

function setCT(btn) {
  // handle two separate groups (timeframe and chart type)
  const siblings = btn.closest('.chart-type-bar');
  // find which group it's in by checking if there's a separator between
  const allBtns = [...siblings.querySelectorAll('.ct-btn')];
  const sepIdx = allBtns.findIndex(b => b.nextElementSibling && b.nextElementSibling.classList.contains('ct-sep'));
  const btnIdx = allBtns.indexOf(btn);
  const groupBtns = btnIdx <= sepIdx ? allBtns.slice(0, sepIdx + 1) : allBtns.slice(sepIdx + 1);
  groupBtns.forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
}

function switchMoverTab(section, tab, btn) {
  const card = btn.closest('.mover-card');
  card.querySelectorAll('.mover-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  ['regular','pre','after'].forEach(t => {
    const el = document.getElementById(section + '-' + t);
    if (el) el.style.display = t === tab ? 'block' : 'none';
  });
}

// Highlight active tab on scroll
window.addEventListener('scroll', () => {
