<script>
function filterBrokers(category, btn) {
  // Update tab state
  btn.closest('.tabs').querySelectorAll('.tab').forEach(t => {
    t.classList.remove('active');
    t.setAttribute('aria-selected', 'false');
  });
  btn.classList.add('active');
  btn.setAttribute('aria-selected', 'true');

  const cards = document.querySelectorAll('.broker-card');
  cards.forEach(card => {
    const cats = card.dataset.category || '';
    card.style.display = (category === 'all' || cats.includes(category)) ? '' : 'none';
  });
}

function sortBrokers(order, btn) {
  btn.closest('.rating-tabs').querySelectorAll('.tab').forEach(t => {
    t.classList.remove('active');
    t.setAttribute('aria-selected', 'false');
  });
  btn.classList.add('active');
  btn.setAttribute('aria-selected', 'true');

  const list = document.getElementById('brokerList');
  const cards = [...list.querySelectorAll('.broker-card')];
  if (order === 'best') {
    cards.sort((a, b) => parseFloat(b.dataset.rating) - parseFloat(a.dataset.rating));
  } else {
    // natural order — no reorder
  }
  cards.forEach(c => list.appendChild(c));
}
</script>
